function shareFrom(s, a, b, T, basis) {
  if (basis === "policy") return Math.min(1, Math.max(0, (b - s) / (b - a)));
  const g = (u) => {
    const x = u - s;
    if (x <= 0) return 0;
    return x < T ? x * x / (2 * T) : T / 2 + (x - T);
  };
  return (g(b) - g(a)) / (b - a);
}
