var YIELD_CURVES = [us_treasury_par_yields_default];
var DATASETS = [...LIFE_TABLES, ...INDEX_DATASETS, ...YIELD_CURVES];
function periodAt(series, k) {
  if (series.frequency === "quarterly") {
    const [y2, q] = series.start.split("-Q").map(Number);
    const n2 = y2 * 4 + (q - 1) + k;
    return `${Math.floor(n2 / 4)}-Q${n2 % 4 + 1}`;
  }
  const [y, m] = series.start.split("-").map(Number);
  const n = y * 12 + (m - 1) + k;
  return `${Math.floor(n / 12)}-${String(n % 12 + 1).padStart(2, "0")}`;
}
function periodYears(period) {
  const q = /^(\d{4})-Q(\d)$/.exec(period);
  if (q) return Number(q[1]) + (Number(q[2]) - 0.5) / 4;
  const [y, m] = period.split("-").map(Number);
  return y + (m - 0.5) / 12;
}
