    judgments: spec.fields.filter((f) => f.judgment).map((f) => ({ field: f.key, label: f.label, default: f.kind === "table" || f.kind === "triangle" ? null : f.default })),
    method: spec.method,
    next: (spec.next ?? []).map((n) => n.tool)
